express-session em produção:
```js
app.set('trust proxy', 1);
app.use(session({
  store: new RedisStore({ client }),
  secret: process.env.SESSION_SECRET, name: 'sid',
  resave: false, saveUninitialized: false,
  cookie: { httpOnly: true, secure: true, sameSite: 'lax', maxAge: 8*3600e3 }
}));
```
No login: `req.session.regenerate(...)` antes de gravar o userId. Sem `trust proxy`, atrás do Nginx o Express acha que é HTTP e o cookie `secure` nunca é enviado — login que 'não pega' em produção.

API Express validando tokens de um IdP:
```js
import { createRemoteJWKSet, jwtVerify } from 'jose';
const JWKS = createRemoteJWKSet(new URL('https://idp/.well-known/jwks.json'));
async function auth(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];
  const { payload } = await jwtVerify(token, JWKS, { issuer: 'https://idp/', audience: 'api-pedidos' });
  req.user = payload; next();
}
```
O `jose` cuida do cache e do refetch por `kid` desconhecido.

```sql
CREATE ROLE api_pedidos LOGIN PASSWORD '...';
GRANT USAGE ON SCHEMA public TO api_pedidos;
GRANT SELECT, INSERT, UPDATE ON pedidos, itens TO api_pedidos;
GRANT SELECT ON clientes TO api_pedidos;  -- lê, nunca altera
GRANT USAGE ON SEQUENCE pedidos_id_seq TO api_pedidos;
```
Um SQLi nessa API não consegue `DROP TABLE`, não lê `usuarios.senha_hash`, não altera clientes. No AutoTrade: API key só com 'Enable Spot Trading', sem 'Enable Withdrawals', restrita ao IP do servidor.

Config perigosa vista em produção: `app.use(cors({ origin: (o, cb) => cb(null, o), credentials: true }))` — reflete qualquer origem com credenciais: um site malicioso lê dados do usuário logado. Correção:
```js
const allow = new Set(['https://app.empresa.com', 'https://central.empresa.com']);
app.use(cors({ origin: (o, cb) => cb(null, !o || allow.has(o)), credentials: true, maxAge: 600 }));
```
E lembre: isso não impede um script Python de bater na API — para isso existe autenticação e rate limiting.

Defesa combinada em Express: cookie de sessão `sameSite: 'lax'`; middleware que para métodos não seguros exige `Origin` na allowlist OU token CSRF válido:
```js
function csrfGuard(req, res, next) {
  if (['GET','HEAD','OPTIONS'].includes(req.method)) return next();
  const origin = req.get('Origin') ?? new URL(req.get('Referer') ?? 'x://x').origin;
  if (!ALLOWED.has(origin)) return res.status(403).end();
  next();
}
```
Em SPA com fetch e header custom, o preflight já barra origem estranha antes do request chegar.

Vulnerável: `db.query(`SELECT * FROM vendedoras WHERE loja = ${req.query.loja} ORDER BY ${req.query.ordem}`)`. `loja=8; DROP TABLE pedidos--`. Correto:
```js
const ORDENS = { nome: 'ven_nome', venda: 'total DESC' };
const ordem = ORDENS[req.query.ordem] ?? 'ven_nome';
await db.query(`SELECT * FROM vendedoras WHERE loja = $1 ORDER BY ${ordem}`, [Number(req.query.loja)]);
```
Valor por parâmetro; identificador por allowlist — nunca pelo input.

Feature 'importar logo do fornecedor por URL' no Central. Atacante envia `http://192.168.0.204:3000/api/tools` — o VisualInspector interno responde e o conteúdo é salvo como 'imagem' que ele baixa depois. Correção:
```js
const { address } = await dns.lookup(new URL(url).hostname);
if (ipaddr.parse(address).range() !== 'unicast') throw new Error('destino bloqueado');
await fetch(url, { redirect: 'manual', signal: AbortSignal.timeout(3000), dispatcher: pinnedTo(address) });
```
Mais regra de egress no firewall: o host da API não fala com a LAN de gestão.

```js
const BASE = path.resolve('/srv/uploads');
app.get('/arquivos/:id', async (req, res) => {
  const meta = await db.arquivos.find(req.params.id);  // id é UUID, nome interno é gerado
  const alvo = path.resolve(BASE, meta.nomeInterno);
  if (!alvo.startsWith(BASE + path.sep)) return res.sendStatus(400);
  res.download(alvo, meta.nomeOriginal);
});
```
O nome que o usuário deu nunca toca o filesystem; o caminho resolvido é verificado mesmo assim.

```js
import argon2 from 'argon2';
const OPTS = { type: argon2.argon2id, memoryCost: 65536, timeCost: 3, parallelism: 1 };
const hash = await argon2.hash(senha, OPTS);          // gera salt, embute parâmetros
const ok = await argon2.verify(user.hash, senha);    // constant-time
if (ok && argon2.needsRehash(user.hash, OPTS)) await salvarHash(await argon2.hash(senha, OPTS));
```
Migração de MD5 legado: no login bem-sucedido (único momento em que você tem a senha em claro), rehash com argon2 e marque o registro.

Tabela de integrações guarda a API key da Binance do usuário. Errado: `Buffer.from(key).toString('base64')`. Certo:
```js
const iv = crypto.randomBytes(12);
const c = crypto.createCipheriv('aes-256-gcm', KEK, iv);
const enc = Buffer.concat([c.update(key, 'utf8'), c.final()]);
salvar({ iv, enc, tag: c.getAuthTag() });
```
KEK vem do cofre/env, nunca do banco. Para 'já cadastrou essa chave?', guarde `HMAC-SHA256(KEK2, key)` como coluna indexada.

```js
import { z } from 'zod';
const Env = z.object({
  NODE_ENV: z.enum(['development','test','production']),
  PORT: z.coerce.number().default(3000),
  DATABASE_URL: z.string().url(),
  SESSION_SECRET: z.string().min(32),
  FEATURE_GARIMPEIRO: z.coerce.boolean().default(false),
});
export const env = Env.parse(process.env); // lança no boot se faltar ou estiver errado
```
A app não sobe com `SESSION_SECRET=changeme` de 8 caracteres.

Nginx exigindo certificado de cliente para a API interna:
```nginx
ssl_client_certificate /etc/nginx/ca-interna.pem;
ssl_verify_client on;
location /api/ {
  proxy_set_header X-Client-CN $ssl_client_s_dn_cn;
  proxy_pass http://api;
}
```
A API confia em `X-Client-CN` só porque o Nginx é o único caminho (rede fechada). Sem mTLS, o mesmo cenário exigiria token por serviço, rotação manual e o risco de token em log.

Nginx:
```nginx
server { listen 80; return 301 https://$host$request_uri; }
server {
  listen 443 ssl http2;
  add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;
}
```
O `always` garante o header também em respostas de erro. Note que o HSTS só é aceito quando recebido via HTTPS válido — enviá-lo na resposta HTTP é ignorado.

```js
const NovoPedido = z.object({
  clienteId: z.number().int().positive(),
  itens: z.array(z.object({ sku: z.string().regex(/^[A-Z0-9-]{4,20}$/), qtd: z.number().int().min(1).max(999) })).min(1).max(200),
  observacao: z.string().max(500).optional(),
}).strict();
app.post('/pedidos', (req, res) => {
  const dados = NovoPedido.parse(req.body);   // 400 se inválido, campos extras rejeitados
  // dados.observacao vai para o banco via $n (SQL) e é escapada pelo React ao exibir (HTML)
});
```

```js
const logger = pino({
  level: process.env.LOG_LEVEL ?? 'info',
  redact: { paths: ['req.headers.authorization', 'req.headers.cookie', '*.senha', '*.password', '*.token', '*.apiKey'], censor: '[REDACTED]' },
});
app.use(pinoHttp({ logger, serializers: { req: (r) => ({ id: r.id, method: r.method, url: r.url, userId: r.user?.id }) } }));
```
Auditoria separada: `audit.info({ actor: userId, action: 'pedido.cancelar', target: pedidoId, ip })` — sem payload, com retenção de 5 anos.
